from rdkit import Chem
from rdkit.Chem import AllChem, rdDepictor
from builder import build_mol
import numpy as np

# --- re-run pseudo-3D assignment (same as stereo4) ---
mol,lab=build_mol()
rdDepictor.Compute2DCoords(mol)
c2=mol.GetConformer(); xy={i:np.array(c2.GetAtomPosition(i))[:2] for i in range(mol.GetNumAtoms())}
molH=Chem.AddHs(mol); N=molH.GetNumAtoms()
con=Chem.Conformer(N); con.Set3D(True)
for i in range(mol.GetNumAtoms()):
    p=xy[i]; con.SetAtomPosition(i,(float(p[0]),float(p[1]),0.))
for i in range(mol.GetNumAtoms(),N):
    nb=molH.GetAtomWithIdx(i).GetNeighbors()[0].GetIdx(); p=xy[nb]
    con.SetAtomPosition(i,(float(p[0]),float(p[1]),0.))
def h_of(label):
    for nb in molH.GetAtomWithIdx(lab[label]).GetNeighbors():
        if nb.GetAtomicNum()==1: return nb.GetIdx()
def setZ(l,z):
    i=lab[l]; p=con.GetAtomPosition(i); con.SetAtomPosition(i,(p.x,p.y,z))
def setHZ(l,z):
    p=con.GetAtomPosition(h_of(l)); con.SetAtomPosition(h_of(l),(p.x,p.y,z))
setZ('OU',+1); setZ('CM',+1); setZ('q2',+1)
setZ('OT',-1); setZ('NA',-1); setZ('OB',-1)
setHZ('T',+1); setHZ('LU',-1); setHZ('LL',+1); setHZ('RL',+1); setHZ('JL',+1); setHZ('Hc',-1); setHZ('g',-1)
molH.RemoveAllConformers(); molH.AddConformer(con, assignId=True)
Chem.AssignStereochemistryFrom3D(molH, confId=0, replaceExistingTags=True)
heavy=Chem.RemoveHs(molH)  # heavy indices == lab, tags set

# --- embed with ETKDG honoring tags ---
def embed_and_signs(heavy):
    m=Chem.AddHs(heavy)
    ps=AllChem.ETKDGv3(); ps.randomSeed=0xC0FFEE
    ok=AllChem.EmbedMolecule(m, ps)
    if ok!=0:
        ps.useRandomCoords=True; AllChem.EmbedMolecule(m, ps)
    AllChem.MMFFOptimizeMolecule(m, maxIters=200)
    conf=m.GetConformer()
    P={i:np.array(conf.GetAtomPosition(i)) for i in range(m.GetNumAtoms())}
    junc=['RU','RL','JU','JL','CMe','Hc']
    M=np.array([P[lab[j]] for j in junc]); cen=M.mean(0)
    U,S,Vt=np.linalg.svd(M-cen); normal=Vt[-1]
    def sd(label):
        return float(np.dot(P[lab[label]]-cen, normal))
    def h(label):
        for nb in m.GetAtomWithIdx(lab[label]).GetNeighbors():
            if nb.GetAtomicNum()==1: return nb.GetIdx()
    res={'OT':sd('OT'),'OU':sd('OU'),'NA':sd('NA'),'CM':sd('CM'),'q2':sd('q2'),'OB':sd('OB')}
    res['H_Hc']=float(np.dot(P[h('Hc')]-cen,normal))
    res['H_RL']=float(np.dot(P[h('RL')]-cen,normal))
    res['H_JL']=float(np.dot(P[h('JL')]-cen,normal))
    # orient so CM positive
    if res['CM']<0:
        res={k:-v for k,v in res.items()}
    return res, m

targets={'OT':-1,'OU':+1,'NA':-1,'CM':+1,'q2':+1,'OB':-1,'H_Hc':-1,'H_RL':+1,'H_JL':+1}
res,m=embed_and_signs(heavy)
print('center  target  measured  OK?')
okall=True
for k,t in targets.items():
    s=1 if res[k]>=0 else -1; ok=(s==t); okall&=ok
    print(f'{k:6s} {t:+d}     {res[k]:+7.3f}   {"OK" if ok else "BAD"}')
print('ALL OK' if okall else 'MISMATCH')
print('ISO:', Chem.MolToSmiles(heavy, isomericSmiles=True))
m2=Chem.RemoveHs(m)
open('check.smi','w').write(Chem.MolToSmiles(heavy, isomericSmiles=True)+'\n')
